1	/**
2	 * @module useEtiquetaScanner
3	 *
4	 * Hook único de leitura de etiquetas QR — Bluetooth (USB scanner) + Câmera.
5	 * Extraído do pattern de `RequisicaoConferenciaModal` pra reuso em separação,
6	 * conferência e recebimento. Cada bip vira um payload tipado e dedupado.
7	 */
8	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
9	import { Html5Qrcode, Html5QrcodeSupportedFormats } from "html5-qrcode";
10	import { wideInfo, wideError } from "@/shared/lib/telemetry/wide-events";
11	import { supabase } from "@/integrations/supabase/client";
12	
13	/**
14	 * Captura device info + scanMode pra cada evento de telemetria. Permite
15	 * ao admin filtrar problemas por dispositivo (ex: "todos os erros vindos de
16	 * tablets Android com USB dongle"). Roda em runtime — userAgent muda raro.
17	 */
18	function getDeviceContext() {
19	  if (typeof window === "undefined") return {};
20	  const nav = window.navigator;
21	  return {
22	    "device.user_agent": nav?.userAgent || "unknown",
23	    "device.platform": nav?.platform || "unknown",
24	    "device.lang": nav?.language || "unknown",
25	    "device.viewport": `${window.innerWidth}x${window.innerHeight}`,
26	    "device.is_secure_context": String(window.isSecureContext ?? "unknown"),
27	    "device.touch": String((nav?.maxTouchPoints ?? 0) > 0),
28	  };
29	}
30	
31	/**
32	 * Persiste evento de telemetria do scanner no Supabase pra admin ver agregado.
33	 * Fire-and-forget — não bloqueia o fluxo do scan se falhar.
34	 */
35	export async function logScannerEvent(payload: {
36	  evento: 'qr_scanned' | 'qr_rejected' | 'qr_duplicate' | 'camera_error';
37	  scan_mode: string;
38	  scan_uid?: string | null;
39	  scan_pid?: string | null;
40	  raw_len?: number | null;
41	  raw_preview?: string | null;
42	  raw_is_only_hex?: boolean | null;
43	  raw_is_odd_len?: boolean | null;
44	  erro_mensagem?: string | null;
45	}) {
46	  try {
47	    if (typeof window === "undefined" || typeof navigator === "undefined") return;
48	    const { data: { user } } = await supabase.auth.getUser();
49	    // eslint-disable-next-line @typescript-eslint/no-explicit-any
50	    await (supabase.from("scanner_telemetry" as any) as any).insert({
51	      ...payload,
52	      usuario_id: user?.id ?? null,
53	      user_agent: navigator.userAgent || null,
54	      platform: navigator.platform || null,
55	      viewport: `${window.innerWidth}x${window.innerHeight}`,
56	      is_secure_ctx: window.isSecureContext ?? null,
57	      is_touch: (navigator.maxTouchPoints ?? 0) > 0,
58	      language: navigator.language || null,
59	    });
60	  } catch {
61	    // não impede fluxo do scan; falha é silenciosa
62	  }
63	}
