121	export function printHTML(html: string, options?: { title?: string }) {
122	  const title = options?.title || 'Impressão';
123	  const iOS = isIOS();
124	
125	  // Wrap fragment as full document if needed
126	  let fullHTML = html;
127	  const hasHtmlTag = /<html[\s>]/i.test(html);
128	  if (!hasHtmlTag) {
129	    fullHTML = `<!DOCTYPE html>
130	<html lang="pt-BR">
131	<head>
132	<meta charset="UTF-8">
133	<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
134	<title>${escapeHTML(title)}</title>
135	</head>
136	<body>
137	${html}
138	</body>
139	</html>`;
140	  }
141	
142	  if (iOS) {
143	    fullHTML = injectIOSToolbar(fullHTML, title);
144	  }
145	
146	  const win = window.open('', '_blank');
147	  if (!win) {
148	    // Popup blocked — fallback: download as HTML file
149	    downloadAsHTML(fullHTML, title);
150	    return;
151	  }
152	
153	  win.document.open();
154	  win.document.write(fullHTML);
155	  win.document.close();
156	
157	  if (!iOS) {
158	    // Desktop/Android: auto-print after load
159	    const triggerPrint = () => {
160	      try {
161	        win.focus();
162	        win.print();
163	      } catch {}
164	    };
165	    if (win.document.readyState === 'complete') {
166	      setTimeout(triggerPrint, 250);
167	    } else {
168	      win.addEventListener('load', () => setTimeout(triggerPrint, 250));
169	    }
